def maxSumMultipleLength(nums, k):
    INF = float("inf")
    mn = [INF] * k
    best = -INF
    s = 0
    for j in range(len(nums) + 1):
        if j:
            s += nums[j - 1]
        c = j % k
        if mn[c] != INF:
            best = max(best, s - mn[c])
        if s < mn[c]:
            mn[c] = s
    return best
